-- Resume only undelivered, still-actionable invitations. Never replay sent mail.
INSERT INTO "notification_deliveries" ("id", "invitationId", "transport", "expiresAt")
SELECT md5('invitation-email:' || i.id), i.id, 'email', to_timestamp(i."expiresAt" / 1000.0)
FROM "invitations" i
WHERE i."acceptedAt" IS NULL AND i."revokedAt" IS NULL
  AND i."expiresAt" > extract(epoch FROM now()) * 1000
  AND i."deliveryStatus" IN ('pending', 'failed')
  AND NOT EXISTS (SELECT 1 FROM "user" u WHERE lower(u.email) = lower(i.email));
